#!/usr/bin/env bash
# Build-time: compile + install HylaFAX+ from source, install IAXmodem (Debian pkg).
# Per-container modem/peer/dialplan config is generated by ipbx-entrypoint.
set -uo pipefail
: "${HYLAFAX_VERSION:?}" "${HYLAFAX_MD5:?}"
HYLAFAX_URL=${HYLAFAX_URL:-https://prdownloads.sourceforge.net/hylafax/hylafax-${HYLAFAX_VERSION}.tar.gz?download}
BUILD_DIR=$(cd "$(dirname "$0")" && pwd)
LOG=/var/log/hylafax-build.log
export DEBIAN_FRONTEND=noninteractive
die(){ echo "HYLAFAX BUILD FAILED: $*" >&2; tail -n 60 "$LOG" >&2 2>/dev/null; exit 1; }

echo "=== HylaFAX+ ${HYLAFAX_VERSION} + IAXmodem ==="
apt-get update >>"$LOG" 2>&1
apt-get install -y --no-install-recommends \
    build-essential libtiff-dev libjbig-dev libjpeg-dev zlib1g-dev libpam0g-dev libssl-dev \
    ghostscript libtiff-tools sharutils gawk psmisc file iaxmodem >>"$LOG" 2>&1 \
  || die "apt install failed"

# Debian's iaxmodem sysv service would run all modems as one unit; we use iaxmodem@.service
/usr/bin/systemctl mask iaxmodem.service >/dev/null 2>&1 || true
rm -f /etc/iaxmodem/ttyIAX* 2>/dev/null

SRC=/usr/src/hylafax
mkdir -p "$SRC" && cd "$SRC" || die "no $SRC"
wget -q -O "hylafax-${HYLAFAX_VERSION}.tar.gz" "$HYLAFAX_URL" || die "download failed: $HYLAFAX_URL"
echo "${HYLAFAX_MD5}  hylafax-${HYLAFAX_VERSION}.tar.gz" | md5sum -c - || die "MD5 mismatch"
tar xzf "hylafax-${HYLAFAX_VERSION}.tar.gz" && cd "hylafax-${HYLAFAX_VERSION}" || die "extract failed"

./configure --nointeractive \
  --with-DIR_BIN=/usr/bin --with-DIR_SBIN=/usr/sbin --with-DIR_LIBEXEC=/usr/sbin \
  --with-DIR_LIB=/usr/lib --with-DIR_LIBDATA=/etc/hylafax --with-DIR_SPOOL=/var/spool/hylafax \
  --with-DIR_MAN=/usr/share/man --with-DIR_LOCKS=/var/lock \
  --with-PATH_GSRIP=/usr/bin/gs --with-TIFFBIN=/usr/bin --with-AFM=no --with-AWK=/usr/bin/gawk \
  --with-PATH_GETTY=/sbin/agetty --with-PATH_VGETTY=/bin/false --with-PATH_EGETTY=/bin/false \
  --with-SYSVINIT=no --with-PAGESIZE="North American Letter" >>"$LOG" 2>&1 \
  || die "configure failed"
make -j"$(nproc)" >>"$LOG" 2>&1 || die "make failed"
make install >>"$LOG" 2>&1      || die "make install failed"

faxsetup -server -nointeractive >>"$LOG" 2>&1 || true
[[ -f /var/spool/hylafax/etc/setup.cache ]] || die "faxsetup did not create setup.cache"
command -v faxq >/dev/null && command -v faxgetty >/dev/null && command -v sendfax >/dev/null \
  || die "HylaFAX+ binaries missing"

# Modem config template (entrypoint stamps out config.ttyIAX<n> from it)
install -m 0644 "$BUILD_DIR/config.iaxmodem.template" /etc/hylafax/config.iaxmodem.template

# Housekeeping jobs
cat > /etc/cron.d/hylafax <<'EOF'
0 * * * *  root  /usr/sbin/faxqclean >/dev/null 2>&1
15 4 * * * root  /usr/sbin/faxcron -info 35 -log 35 -rcv 35 >/dev/null 2>&1
EOF

cd / && rm -rf "$SRC"
echo "=== HylaFAX+ $(faxstat -h 2>/dev/null | head -1 || echo installed) ==="
